<script setup lang="ts">
import {title as displayTitle,sourceName,indicator,utc,time as beijingTime,duration,http} from '../presentation/zh';
import {ref,onMounted} from 'vue';import {post,safeArticleUrl} from '../api/client';const props=defineProps<{token:string}>();
const search=ref(''),rows=ref<Record<string,any>[]>([]),relations=ref<Record<string,any>[]>([]),detail=ref<Record<string,any>>(),error=ref(''),kind=ref('BUSINESS_FACT');
const reviewTarget=ref<Record<string,any>>(),reviewDecision=ref('RETURN_FOR_PROOF'),reviewReason=ref(''),reviewExcerpt=ref(''),reviewEvidence=ref(''),reviewLimitations=ref(''),reviewActor=ref(''),history=ref<Record<string,any>[]>([]);
async function reviewOpen(r:Record<string,any>){reviewTarget.value=r;reviewEvidence.value=r.evidence_id||'';history.value=await post('/relations/'+r.id+'/history',props.token);}
async function submitReview(){if(!reviewTarget.value)return;try{await post('/relations/'+reviewTarget.value.id+'/review',props.token,{decision:reviewDecision.value,actor:reviewActor.value,reason:reviewReason.value,evidenceId:reviewEvidence.value||null,excerpt:reviewExcerpt.value||null,limitations:reviewLimitations.value});history.value=await post('/relations/'+reviewTarget.value.id+'/history',props.token);await load();}catch{error.value='关系审核未通过：请核对真实双方身份、明确关系披露、证据和公开时间，不能仅凭名称共现接受';}}
const types:Record<string,string>={COUNTRY:'国家',REGION:'地区',CENTRAL_BANK:'中央银行',REGULATOR:'监管机构',ORGANIZATION:'机构候选',COMPANY:'企业',SECURITY:'证券',EXCHANGE:'证券交易所',FUND:'基金',INDUSTRY:'行业',COMMODITY:'商品',CURRENCY:'货币',INDICATOR:'经济指标',INDEX:'指数',SECTOR:'产业'};
async function load(){try{rows.value=await post('/entities/search',props.token,{search:search.value,page:0});relations.value=await post('/entities/relations',props.token,{kind:kind.value});}catch{error.value='企业主数据与关系暂不可用';}}
async function open(id:string){try{detail.value=await post('/entities/'+id,props.token);}catch{error.value='实体证据不足或暂不可用';}}
onMounted(()=>void load());
</script>
<template><section class="panel feed"><h2>全球企业与市场联动</h2><p>业务事实、行业归属、宏观假设、人工智能（AI）候选与统计关系分别管理。名称出现不代表公司身份或客户供应商关系已核实。</p><p v-if="error">{{error}}</p><input v-model="search" placeholder="搜索真实机构名称"><button @click="load">查询实体主数据</button><select v-model="kind" aria-label="关系证据分类" @change="load"><option value="ACCOUNTING_CONSOLIDATION">会计并表母公司</option><option value="LEGAL_IDENTITY">法人身份对应</option><option value="BUSINESS_FACT">企业真实业务关系</option><option value="INDUSTRY_MEMBERSHIP">行业归属</option><option value="MACRO_HYPOTHESIS">宏观敏感性假设</option><option value="AI_CANDIDATE">人工智能（AI）待核验候选</option><option value="STATISTICAL">历史统计关系</option></select><p>当前已核实关系 {{relations.filter(r=>r.status==='VERIFIED').length}} · 待审核关系 {{relations.filter(r=>r.status==='PENDING').length}}</p><p v-if="!relations.length">暂无真实关系数据，证据不足</p><article v-for="r in relations" :key="r.id"><p>{{r.subject}} → {{r.object}} · {{r.status==='VERIFIED'?'已审核':'待审核'}}</p><p>{{r.explanation}} · 有效时间 <time :title="'UTC原值：'+utc(r.effective_from)">{{beijingTime(r.effective_from)}}</time> / <time :title="'UTC原值：'+utc(r.effective_until)">{{beijingTime(r.effective_until)}}</time></p><code>{{r.raw_content_hash||'证据不足'}}</code><a v-if="safeArticleUrl(r.source_url||'')" :href="r.source_url" target="_blank" rel="noopener noreferrer">查看关系原始证据</a><button @click="reviewOpen(r)">审核关系与历史</button></article><section v-if="reviewTarget"><h3>企业关系证据审核</h3><p>{{reviewTarget.subject}} → {{reviewTarget.object}} · {{reviewTarget.type}}</p><select v-model="reviewDecision" aria-label="关系审核决定"><option value="RETURN_FOR_PROOF">退回补证</option><option value="REJECT">驳回</option><option value="ACCEPT">接受正式证据</option></select><input v-model="reviewActor" placeholder="审核责任人"><input v-model="reviewEvidence" placeholder="真实证据编号"><textarea v-model="reviewExcerpt" placeholder="原文中明确双方与关系的逐字摘录"/><textarea v-model="reviewReason" placeholder="审核依据（至少10字）"/><textarea v-model="reviewLimitations" placeholder="证据局限与适用范围"/><button @click="submitReview">提交审核并留痕</button><article v-for="h in history" :key="h.id"><p><time :title="'UTC原值：'+utc(h.created_at)">{{beijingTime(h.created_at)}}</time> · {{h.actor}} · {{({ACCEPT:'接受',REJECT:'驳回',RETURN_FOR_PROOF:'退回补证'} as Record<string,string>)[h.decision]}}</p><p>{{h.reason}} · {{h.limitations}}</p></article></section><article v-for="e in rows" :key="e.id"><h3>{{e.chinese_name||'法人中文名称待核验'}}</h3><p>{{types[e.type]||'类型待确认'}} · {{e.status==='VERIFIED'?'身份名称有官方证据':'待审核候选'}} · 法律名称 {{e.legal_name||'未知'}} · 国家 {{e.country||'未知'}} · 官方标识 {{e.official_identifier||'未知'}}</p><button @click="open(e.id)">查看实体、证券与历史证据</button></article><section v-if="detail"><h3>实体历史与来源</h3><p>{{detail.entity.official_name}}</p><p v-if="!detail.profiles.length">法律实体资料尚未取得真实披露，不补造信息</p><article v-for="p in detail.profiles" :key="p.id"><p>{{p.original_name}} · 法律名称 {{p.legal_name||'未知'}} · 标识 {{p.official_identifier||'未知'}} · {{p.latest_review==='VERIFIED'?(detail.entity.source_id==='GLEIF'?'法人登记字段校验已记录':'人工身份审核已记录'):p.latest_review==='CONFLICT'?'身份证据存在冲突':'待审核历史版本'}}</p><p>有效期 <time :title="'UTC原值：'+utc(p.valid_from)">{{beijingTime(p.valid_from)}}</time> / <time :title="'UTC原值：'+utc(p.valid_to)">{{beijingTime(p.valid_to)}}</time></p><code>{{p.raw_content_hash}}</code><a v-if="safeArticleUrl(p.source_url)" :href="p.source_url" target="_blank" rel="noopener noreferrer">查看原始披露</a></article><p v-if="!detail.securities.length">暂无真实证券上市资料</p><p v-for="s in detail.securities" :key="s.id">证券代码 {{s.ticker||'未知'}} · 交易所 {{s.exchange_id||'未知'}} · 发行人 {{s.issuer_id||'未知'}} · 上市状态待核验</p></section></section></template>
